src = 'y + 2 * z'
tokens = []
i = 0
while i < len(src):
    c = src[i]
    if c == ' ':
        i = i + 1
    elif c.isdigit():
        j = i
        while j < len(src) and src[j].isdigit():
            j = j + 1
        tokens.append(('num', src[i:j]))
        i = j
    elif c.isalpha():
        j = i
        while j < len(src) and src[j].isalnum():
            j = j + 1
        tokens.append(('id', src[i:j]))
        i = j
    else:
        tokens.append((c, c))
        i = i + 1
print(tokens)
